SELECT orders.channel, SUM(CASE WHEN shipments.carrier = 'Kerry' THEN shipments.cost ELSE 0 END) AS kerry_cost, MAX(shipments.cost) - MIN(shipments.cost) AS cost_range FROM shipments RIGHT OUTER JOIN orders ON shipments.order_id = orders.id LEFT OUTER JOIN stores ON orders.store_id = stores.id WHERE YEAR(stores.opened_date) = 2025 GROUP BY orders.channel ORDER BY orders.channel, kerry_cost DESC LIMIT 50;
